// Parse incoming event payload
const body = $input.item.json.body ?? $input.item.json;

const event    = body.event    ?? 'unknown_event';
const severity = body.severity ?? 'info';
const username = body.username ?? 'system';
const details  = body.details  ?? {};

const score = severity === 'critical' ? 3
            : severity === 'warning'  ? 2
            : 1;

return [{ json: {
  event,
  severity,
  username,
  details: JSON.stringify(details),
  enriched_at: new Date().toISOString(),
  source: 'n8n-workflow-03',
  severity_score: score
}}];

const e = $('Code: Enrich Event').item.json;
const emoji = e.severity === 'critical' ? '🚨' : '⚠️';
return [{ json: {
  alert_type: e.event.toUpperCase(),
  message: `${emoji} RAG ALERT [${e.severity.toUpperCase()}] | Event: ${e.event} | User: ${e.username} | ${e.enriched_at}`,
  event: e.event,
  severity: e.severity,
  username: e.username,
  timestamp: e.enriched_at
}}];
